import type { ReactNode } from 'react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type {
    AgentConversation,
    AgentConversationEntry,
    AgentConversationEvent,
    AgentConversationEventEntry,
    AgentConversationMessageEntry,
